#include <algorithm>
#include <cstdio>
using namespace std;

typedef long long ll;

int main() {
    int n, m;

    while(cin >> n >> m) {
        if(n == 0 && m == 0) break;

        // Optimized initialization of the adjacency matrix g using a flat array
        float *g = new float[n * n]; // Dynamically allocate memory for adjacency matrix
        for(int i = 0; i < n * n; i++) {
            cin >> g[i]; // Directly reading input in a single loop
        }

        float *dp = new float[n]; // Dynamically allocate memory for dp array
        fill(dp, dp + n, -1);
        dp[0] = 1.0; // Initialize first element

        for(int i = 2; i <= m; i++) {
            float max_prev = dp[0]; // Start with the first element as max
            for(int j = 1; j < n; j++) {
                max_prev = max(max_prev, dp[j]); // Use std::max to find maximum
            }
            for(int j = 0; j < n; j++) {
                dp[j] = max_prev * g[j]; // Update the dp array using flat indexing
            }
        }

        float ans = *max_element(dp, dp + n); // Use std::max_element for better performance
        printf("%.2f\n", ans);

        delete[] g; // Free allocated memory
        delete[] dp; // Free allocated memory
    }
}

