int main() {
    int n, m;

    while(cin >> n >> m) {
        if(n == 0 && m == 0) break;

        // Use a flat array for adjacency matrix to improve locality
        vector<float> g(n * n);
        for(int i = 0; i < n * n; i++) {
            cin >> g[i];  // Read input in a single loop into a flat array
        }

        // Optimized initialization of the dp table using a single array
        vector<float> dp(n);
        fill(dp.begin(), dp.end(), 1.0); // Set all dp[1][i] to 1.0 initially

        for(int i = 2; i <= m; i++) {
            vector<float> new_dp(n); // New dp for current iteration
            fill(new_dp.begin(), new_dp.end(), 0); // Reset new_dp for the current iteration
            for(int j = 0; j < n; j++) {
                for(int k = 0; k < n; k++) {
                    new_dp[j] = max(new_dp[j], dp[k] * g[k * n + j]); // Using the new_dp for current values
                }
            }
            swap(dp, new_dp); // Swap dp with new_dp to reduce memory usage
        }

        float ans = *max_element(dp.begin(), dp.end()); // Find the maximum in dp
        printf("%.2f\n", ans);
    }
}

