    int n, m;

    while(cin >> n >> m) {
        if(n == 0 && m == 0) break;

        // Use a flat array for adjacency matrix to improve locality
        vector<float> g(n * n);
        for(int i = 0; i < n * n; i++) {
            cin >> g[i];  // Read input in a single loop into a flat array
        }

        vector<vector<float>> dp(m + 1, vector<float>(n, 0));
        dp[1].assign(n, 1.0); // Set all dp[1][i] to 1.0

        for(int i = 2; i <= m; i++) {
            for(int j = 0; j < n; j++) {
                for(int k = 0; k < n; k++) {
