using namespace std;

typedef long long ll;

int main() {
    int n, m;

    while(cin >> n >> m) {
        if(n == 0 && m == 0) break;

        // Efficient initialization of the adjacency matrix g
        vector<vector<float>> g(n, vector<float>(n));
        for(int i = 0; i < n * n; i++) {
            cin >> g[i / n][i % n]; // Directly reading input in a single loop
        }

        vector<float> dp(n, -1);
        fill(dp.begin(), dp.end(), 1.0); // Initialize all to 1.0

        for(int i = 2; i <= m; i++) {
            float max_prev = *max_element(dp.begin(), dp.end()); // Get max from previous row
            for(int j = 0; j < n; j++) {
                dp[j] = max_prev * g[0][j]; // Update the dp array
            }
        }

        float ans = *max_element(dp.begin(), dp.end());
        printf("%.2f\n", ans);
    }
}

